from pathlib import Path
import re

# Schema: all independent-review operations require a dedicated reviewer context identity.
p=Path('workflow-schema.js'); s=p.read_text()
old="function operationContract(stage,operation){const operations=STAGE_OPERATIONS[stage]||['COMPLETE'];if(!operations.includes(operation))return null;const override=OPERATION_CONTRACT_OVERRIDES[stage]?.[operation]||{};let scopeRequirements=override.scopeRequirements||SCOPE_REQUIREMENTS[stage]||[];if((stage===17||stage===19)&&!['EXECUTE_RUN','VERIFY'].includes(operation))scopeRequirements=scopeRequirements.filter(key=>key!=='runId'&&key!=='contextId');return Object.freeze({operation,readCollections:Object.freeze(override.readCollections||READ_COLLECTIONS[stage]||[]),agentWritableCollections:Object.freeze(override.agentWritableCollections||STAGE_COLLECTIONS[stage]||[]),allowedStageData:Object.freeze(override.allowedStageData||STAGE_CONTRACTS[stage]?.allowedStageData||[]),applicationCollections:Object.freeze(APPLICATION_COLLECTIONS[stage]||[]),humanActions:Object.freeze(HUMAN_ACTIONS[stage]||[]),scopeRequirements:Object.freeze(scopeRequirements)});}"
new="function operationContract(stage,operation){const operations=STAGE_OPERATIONS[stage]||['COMPLETE'];if(!operations.includes(operation))return null;const override=OPERATION_CONTRACT_OVERRIDES[stage]?.[operation]||{};let scopeRequirements=override.scopeRequirements||SCOPE_REQUIREMENTS[stage]||[];if((stage===17||stage===19)&&!['EXECUTE_RUN','VERIFY'].includes(operation))scopeRequirements=scopeRequirements.filter(key=>key!=='runId'&&key!=='contextId');const independentReview=stage===9||stage===12||stage===23||stage===24||((stage===17||stage===19)&&operation==='VERIFY');if(independentReview&&!scopeRequirements.includes('contextId'))scopeRequirements=[...scopeRequirements,'contextId'];return Object.freeze({operation,readCollections:Object.freeze(override.readCollections||READ_COLLECTIONS[stage]||[]),agentWritableCollections:Object.freeze(override.agentWritableCollections||STAGE_COLLECTIONS[stage]||[]),allowedStageData:Object.freeze(override.allowedStageData||STAGE_CONTRACTS[stage]?.allowedStageData||[]),applicationCollections:Object.freeze(APPLICATION_COLLECTIONS[stage]||[]),humanActions:Object.freeze(HUMAN_ACTIONS[stage]||[]),scopeRequirements:Object.freeze(scopeRequirements)});}"
assert old in s, 'workflow-schema target missing'; s=s.replace(old,new,1); p.write_text(s)

# Engine: reviewer contexts never consume production-run placeholders, and external identifiers participate in reuse detection.
p=Path('workflow-engine.js'); s=p.read_text()
old="function registerFreshContext(project,{stage=project.activeStage,externalContextIdentifier,operatorLabel='HUMAN_OPERATOR'}={}){"
new="function registerFreshContext(project,{stage=project.activeStage,externalContextIdentifier,operatorLabel='HUMAN_OPERATOR',purpose='GENERAL'}={}){"
assert old in s, 'registerFreshContext signature missing'; s=s.replace(old,new,1)
old="  let record=current.find(record=>placeholder.has(upper(recordValue(record,'EXTERNAL_CONTEXT_IDENTIFIER'))));\n  if(record){record.fields=record.fields&&typeof record.fields==='object'?record.fields:{};record.fields.EXTERNAL_CONTEXT_IDENTIFIER=identifier;record.EXTERNAL_CONTEXT_IDENTIFIER=identifier;record.fulfilledAt=now();record.fulfilledBy=operatorLabel;record.identityAssurance='SELF_ASSERTED';refreshRecordHashes(record,'freshContexts');}\n  else record=commandRecord(project,'freshContexts',{EXTERNAL_CONTEXT_IDENTIFIER:identifier,ROLE:core.STAGES[Number(stage)-1]?.role||'UNKNOWN',ITERATION_ID:iterationId,RUN_ID:'NOT APPLICABLE',AUTHORIZED_PROJECT_INPUTS:project.job.CURRENT_INPUT_VERSION||'UNKNOWN',AUTHORIZED_EXTERNAL_SOURCE_MATERIAL:project.job.CURRENT_SOURCE_SET_VERSION||'NOT APPLICABLE',FROZEN_ARTIFACT_VERSIONS:'CURRENT AUTHORIZED VERSIONS',TOOL_AVAILABILITY:'UNKNOWN',CONTAMINATION_STATUS:'UNKNOWN',OUTPUT_IDENTITY:'UNKNOWN',DEVIATIONS:'NONE RECORDED',EVIDENCE:'Context identifier supplied by operator.',USABILITY_DETERMINATION:'UNKNOWN'},{stage,source:'HUMAN_INPUT'});"
new="  const reviewer=upper(purpose)==='REVIEWER';let record=reviewer?null:current.find(record=>placeholder.has(upper(recordValue(record,'EXTERNAL_CONTEXT_IDENTIFIER'))));\n  if(record){record.fields=record.fields&&typeof record.fields==='object'?record.fields:{};record.fields.EXTERNAL_CONTEXT_IDENTIFIER=identifier;record.EXTERNAL_CONTEXT_IDENTIFIER=identifier;record.fulfilledAt=now();record.fulfilledBy=operatorLabel;record.identityAssurance='SELF_ASSERTED';refreshRecordHashes(record,'freshContexts');}\n  else record=commandRecord(project,'freshContexts',{EXTERNAL_CONTEXT_IDENTIFIER:identifier,ROLE:reviewer?`${core.STAGES[Number(stage)-1]?.role||'UNKNOWN'} — INDEPENDENT REVIEWER`:core.STAGES[Number(stage)-1]?.role||'UNKNOWN',ITERATION_ID:iterationId,RUN_ID:'NOT APPLICABLE',AUTHORIZED_PROJECT_INPUTS:project.job.CURRENT_INPUT_VERSION||'UNKNOWN',AUTHORIZED_EXTERNAL_SOURCE_MATERIAL:project.job.CURRENT_SOURCE_SET_VERSION||'NOT APPLICABLE',FROZEN_ARTIFACT_VERSIONS:'CURRENT AUTHORIZED VERSIONS',TOOL_AVAILABILITY:'UNKNOWN',CONTAMINATION_STATUS:'UNKNOWN',OUTPUT_IDENTITY:'UNKNOWN',DEVIATIONS:'NONE RECORDED',EVIDENCE:reviewer?'Dedicated independent reviewer context identifier supplied by operator.':'Context identifier supplied by operator.',USABILITY_DETERMINATION:'UNKNOWN'},{stage,source:reviewer?'HUMAN_REVIEWER_CONTEXT':'HUMAN_INPUT'});"
assert old in s, 'registerFreshContext body missing'; s=s.replace(old,new,1)
old="genExternal=String(recordValue(genRecord,'EXTERNAL_CONTEXT_IDENTIFIER')||'');if(!ver)return {determination:'UNKNOWN',reasons:['Verifier context identity is unavailable.'],evidence:[]};if(ver===gen||genExternal&&ver===genExternal)return {determination:'VIOLATED',reasons:['Verifier reuses the generator context.'],evidence:[gen,ver]};"
new="genExternal=String(recordValue(genRecord,'EXTERNAL_CONTEXT_IDENTIFIER')||''),verExternal=String(recordValue(verRecord,'EXTERNAL_CONTEXT_IDENTIFIER')||'');if(!ver)return {determination:'UNKNOWN',reasons:['Verifier context identity is unavailable.'],evidence:[]};if(ver===gen||(verExternal&&genExternal&&upper(verExternal)===upper(genExternal))||(genExternal&&upper(ver)===upper(genExternal)))return {determination:'VIOLATED',reasons:['Verifier reuses the generator context.'],evidence:[gen,ver]};"
assert old in s, 'independence comparison target missing'; s=s.replace(old,new,1); p.write_text(s)

# Prompt selection: verifier context and target run are separate identities.
p=Path('prompt-engine.js'); s=p.read_text()
old="function contextRecordsFor(state,collection,scope,plan,stage){let selected=selectedContextRecords(state,collection,scope);"
new="function contextRecordsFor(state,collection,scope,plan,stage){const verifierStage=stage===12||((stage===17||stage===19)&&scope?.contextId&&plan);const selectionScope=verifierStage&&collection==='runs'?{...scope,contextId:null}:scope;let selected=selectedContextRecords(state,collection,selectionScope);if(verifierStage&&collection==='freshContexts'&&scope?.contextId)selected=selected.filter(record=>recordId(record,'freshContexts')===String(scope.contextId));"
assert old in s, 'prompt context selector missing'; s=s.replace(old,new,1)
m=re.search(r"const PROMPT_ENGINE_VERSION='closed-loop-prompt-engine/(\d+)';",s); assert m; v=int(m.group(1))+1; s=s[:m.start()]+f"const PROMPT_ENGINE_VERSION='closed-loop-prompt-engine/{v}';"+s[m.end():]; p.write_text(s)

# UI: independently reviewed operations must register a reviewer context before exposing/saving a controlling prompt.
p=Path('app-core.js'); s=p.read_text()
old="function currentReviewerContext(n){return engine.records(current,'freshContexts').filter(r=>engine.isActiveRecord(r)&&Number(r.stage)===Number(n)).at(-1)||null;}"
new="function reviewerOperation(n){const op=selectedOperation(Number(n));return [9,12,23,24].includes(Number(n))||([17,19].includes(Number(n))&&op==='VERIFY');}\nfunction currentReviewerContext(n){const noRun=value=>['','NONE','NOT APPLICABLE','UNASSIGNED','PENDING'].includes(String(value??'').trim().toUpperCase());return engine.records(current,'freshContexts').filter(r=>engine.isActiveRecord(r)&&Number(r.stage)===Number(n)&&noRun(recordValue(r,'RUN_ID')||r.scope?.runId)).at(-1)||null;}"
assert old in s, 'currentReviewerContext target missing'; s=s.replace(old,new,1)
start=s.index('function promptOptions(n){'); end=s.index('\nconst operatorScopeKeys',start)
new_prompt="function promptOptions(n){const operation=selectedOperation(n),options={operation},requirements=schema.operationContract(n,operation)?.scopeRequirements||[],requiresRun=requirements.includes('runId'),requiresContext=requirements.includes('contextId')||reviewerOperation(n),reviewer=reviewerOperation(n);if(requiresRun){const run=selectedRun(n);if(run){const runId=engine.recordId(run,'runs'),generatorContextId=String(recordValue(run,'CONTEXT_ID')||run.relationships?.CONTEXT_ID||run.scope?.contextId||''),scope={runId};if(reviewer){const context=currentReviewerContext(n);if(context)scope.contextId=engine.recordId(context,'freshContexts');}else if(generatorContextId)scope.contextId=generatorContextId;options.scope=scope;}}else if(requiresContext){const context=currentReviewerContext(n);if(context)options.scope={contextId:engine.recordId(context,'freshContexts')};}return options;}"
s=s[:start]+new_prompt+s[end:]
s=s.replace("if([9,23,24].includes(Number(n))&&!currentReviewerContext(n))return 'CONTROLLING INSTRUCTION UNAVAILABLE","if(reviewerOperation(n)&&!currentReviewerContext(n))return 'CONTROLLING INSTRUCTION UNAVAILABLE",1)
s=s.replace("function reviewerContextMarkup(n,locked){if(![9,23,24].includes(n)||locked)return '';","function reviewerContextMarkup(n,locked){if(!reviewerOperation(n)||locked)return '';",1)
old="const ctx=currentReviewerContext(n),external=ctx?String(engine.recordValue(ctx,'EXTERNAL_CONTEXT_IDENTIFIER')||'').trim():'',preflight=n===9,reference=preflight?'the context that authored the Stage 08 production instruction':'the Stage 21 product-generation context';"
new="const ctx=currentReviewerContext(n),external=ctx?String(engine.recordValue(ctx,'EXTERNAL_CONTEXT_IDENTIFIER')||'').trim():'',preflight=n===9,runReview=n===12||([17,19].includes(n)&&selectedOperation(n)==='VERIFY'),reference=preflight?'the context that authored the Stage 08 production instruction':runReview?'the production context that generated the selected run':'the Stage 21 product-generation context';"
assert old in s, 'reviewer reference target missing'; s=s.replace(old,new,1)
s=s.replace("Use a new external conversation/context that did not perform ${preflight?'Stage 08 instruction authoring':'product generation'}.","Use a new external conversation/context that did not perform ${preflight?'Stage 08 instruction authoring':runReview?'the selected run generation':'product generation'}.",1)
s=s.replace("allowFresh=schema.STAGE_CONTRACTS[n].supportCollections.includes('freshContexts')&&![9,23,24].includes(n)","allowFresh=schema.STAGE_CONTRACTS[n].supportCollections.includes('freshContexts')&&!reviewerOperation(n)",1)
s=s.replace("if([23,24].includes(Number(n))&&!currentReviewerContext(n))return `<div class=\"notice warn\"><strong>Open a fresh independent reviewer context first.</strong>","if(reviewerOperation(n)&&!currentReviewerContext(n))return `<div class=\"notice warn\"><strong>Open a fresh independent reviewer context first.</strong>",1)
s=s.replace("if([23,24].includes(Number(n))&&!currentReviewerContext(n))throw new Error('Register a fresh independent reviewer context before saving or copying this reviewer instruction.');","if(reviewerOperation(n)&&!currentReviewerContext(n))throw new Error('Register a fresh independent reviewer context before saving or copying this reviewer instruction.');",1)
s=s.replace("engine.registerFreshContext(next,{stage:current.activeStage,externalContextIdentifier,operatorLabel});","engine.registerFreshContext(next,{stage:current.activeStage,externalContextIdentifier,operatorLabel,purpose:reviewerOperation(current.activeStage)?'REVIEWER':'GENERAL'});",1)
